typedef float rational_t;
typedef float vm_num_t;

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  void* my_thread;
protected:
  void move_SP(int n) { SP += n; }
public:
  char* get_SP() const { return SP; }
  void pop(int n) { move_SP(-n); }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    function(script_library_class* slc, const char* n);
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class vector3d
{
public:
  typedef rational_t T;
  T x, y, z;
  inline T length2() const
  { return x*x + y*y + z*z; }
};

class slf_vector3d_length2_t : public script_library_class::function
{
public:
  slf_vector3d_length2_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
  struct parms_t
  {
    vector3d me;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vm_num_t result = parms->me.length2();
    if (!stack.push((char*)&result,sizeof(result)) )
      error("script stack overflow");
    return true;
  }
};
